"""Amorces standard des guides de conversation Wikivoyage, traduites dans les langues d'interface.

Les guides du Wikivoyage anglais partagent un même gabarit de phrases d'amorce. `phrasebook_fr`
les rend en français ; cette table les rend dans les autres langues de l'interface, pour que les
cours de conversation soient lisibles dans la langue de l'apprenant. Ordre des colonnes : es, de,
it, pt, ja, zh, ko, lt, tl. Les nombres sont rendus en chiffres, compris de tous.

Traductions écrites par une IA, non relues par des locuteurs natifs (surtout lt et tl).
"""
import re

COLS = ['es', 'de', 'it', 'pt', 'ja', 'zh', 'ko', 'lt', 'tl']

_PAREN = re.compile(r'\([^)]*\)')


def norm(s: str) -> str:
    s = _PAREN.sub(' ', s)
    s = s.replace('’', "'").replace('“', '').replace('”', '')
    s = re.sub(r'[,.!?:;¿¡]', ' ', s)
    s = re.sub(r'_+', '_', s)
    s = re.sub(r'\s+', ' ', s).strip().lower()
    return s


