_ROWS.update(_MORE)

TABLE = {norm(k): v for k, v in _ROWS.items()}
for _k, _v in NUMBERS.items():
    TABLE[norm(_k)] = tuple([_v] * len(COLS))


def translate(english: str, lang: str) -> str | None:
    """Traduction de l'amorce dans `lang`, ou None si elle n'est pas dans la table."""
    key = norm(english)
    if re.fullmatch(r'[\d\s,.]+', key):
        return english.strip()      # un nombre écrit en chiffres se lit dans toutes les langues
    row = TABLE.get(key) or TABLE.get(key.replace('"', ''))
    if not row or lang not in COLS:
        return None
    return row[COLS.index(lang)]
